"use client"

import { useState } from "react"
import type { ComponentProps, ReactNode } from "react"

import { zodResolver } from "@hookform/resolvers/zod"
import { maskResolver, useViraMask } from "@virastack/mask"
import { useViraPassword } from "@virastack/password"
import { useForm } from "react-hook-form"

import { Button } from "@/components/ui/button"
import { Field, FieldError, FieldLabel } from "@/components/ui/field"
import { Input } from "@/components/ui/input"
import { AuthLink } from "@/features/auth/components/AuthLink"
import { PasswordInput } from "@/features/auth/components/PasswordInput"
import { PasswordStrength } from "@/features/auth/components/PasswordStrength"
import { RegisterSuccess } from "@/features/auth/components/RegisterSuccess"
import {
  LOGIN_ROUTE,
  PASSWORD_POLICY,
  REGISTER_MASKS
} from "@/features/auth/constants/auth.constants"
import { useRegister } from "@/features/auth/hooks/use-register"
import { registerFormSchema } from "@/features/auth/schemas/auth.schema"
import type { RegisteredUser, RegisterFormInput } from "@/features/auth/schemas/auth.schema"

const EMPTY_VALUES: RegisterFormInput = {
  firstName: "",
  lastName: "",
  username: "",
  email: "",
  password: "",
  confirmPassword: ""
}

type TextFieldName = Exclude<keyof RegisterFormInput, "password" | "confirmPassword">

export function RegisterForm() {
  const registerAccount = useRegister()
  const [created, setCreated] = useState<RegisteredUser | null>(null)
  const form = useForm<RegisterFormInput>({
    resolver: maskResolver(REGISTER_MASKS, zodResolver(registerFormSchema)),
    defaultValues: EMPTY_VALUES
  })
  // The masks take the name and username fields; the password hook below takes the rest.
  const masked = useViraMask(form, REGISTER_MASKS)
  const { errors, isSubmitting } = form.formState
  // Bound to the form: values, `register()` and re-checking the confirmation come from it. Zod
  // still validates, with the same policy, since a resolver skips `register` rules.
  const { password, confirmPassword } = useViraPassword(form, {
    password: {
      policy: PASSWORD_POLICY,
      forbidden: ["firstName", "lastName", "username", "email"]
    },
    confirmPassword: { matchWith: "password" }
  })

  const onSubmit = form.handleSubmit(async (input) => {
    try {
      setCreated(await registerAccount.mutateAsync(input))
      // The form stays mounted under the result, so the password leaves it now.
      form.reset(EMPTY_VALUES)
    } catch {
      form.setError("root.server", { message: "Could not create the account. Try again." })
    } finally {
      // The mutation's variables hold the password: drop them once the answer is in.
      registerAccount.reset()
    }
  })

  if (created) return <RegisterSuccess user={created} onReset={() => setCreated(null)} />

  const textField = (
    name: TextFieldName,
    label: string,
    field: ComponentProps<typeof Input>
  ): ReactNode => {
    const error = errors[name]?.message

    return (
      <Field data-invalid={Boolean(error)}>
        <FieldLabel htmlFor={name}>{label}</FieldLabel>
        <Input {...field} id={name} aria-describedby={error ? `${name}-error` : undefined} />
        {error ? <FieldError id={`${name}-error`}>{error}</FieldError> : null}
      </Field>
    )
  }

  return (
    <div className="flex flex-col gap-6">
      {/* `post`: before hydration the browser submits natively, and a GET puts the password in the URL. */}
      <form method="post" onSubmit={onSubmit} noValidate className="flex flex-col gap-4">
        <div className="grid gap-4 sm:grid-cols-2">
          {textField("firstName", "First name", masked.firstName)}
          {textField("lastName", "Last name", masked.lastName)}
        </div>
        {textField("username", "Username", masked.username)}
        {textField("email", "Email", {
          ...form.register("email"),
          type: "email",
          autoComplete: "email",
          "aria-invalid": Boolean(errors.email)
        })}
        <Field data-invalid={Boolean(errors.password)}>
          <FieldLabel htmlFor={password.inputProps.id}>Password</FieldLabel>
          <PasswordInput
            password={password}
            errorId={errors.password && "password-error"}
            capsLockHint="Caps Lock is on"
          />
          {errors.password ? (
            <FieldError id="password-error">{errors.password.message}</FieldError>
          ) : null}
          <PasswordStrength strength={password.strength} strengthProps={password.strengthProps} />
        </Field>
        <Field data-invalid={Boolean(errors.confirmPassword)}>
          <FieldLabel htmlFor={confirmPassword.inputProps.id}>Confirm password</FieldLabel>
          <PasswordInput
            password={confirmPassword}
            errorId={errors.confirmPassword && "confirmPassword-error"}
            capsLockHint="Caps Lock is on"
          />
          {errors.confirmPassword ? (
            <FieldError id="confirmPassword-error">{errors.confirmPassword.message}</FieldError>
          ) : null}
        </Field>
        {errors.root?.server ? (
          <p role="alert" className="text-sm text-destructive">
            {errors.root.server.message}
          </p>
        ) : null}
        <Button type="submit" disabled={isSubmitting}>
          {isSubmitting ? "Creating account…" : "Create account"}
        </Button>
      </form>
      <p className="text-center text-sm text-muted-foreground">
        Already have an account?{" "}
        <AuthLink
          href={LOGIN_ROUTE}
          className="font-medium text-foreground underline underline-offset-4"
        >
          Sign in
        </AuthLink>
      </p>
    </div>
  )
}

// `/server`: the same API without `"use client"`, for files the server reads too.
import { definePreset } from "@virastack/mask/server"
import { definePolicy } from "@virastack/password/strength"

/** DummyJSON's sign-in. Point it at your API's. */
export const LOGIN_PATH = "/auth/login"
/** DummyJSON answers as if the account was created, but it does not store it. */
export const REGISTER_PATH = "/users/add"

/** Where the pages live in this app. The forms link to each other through these. */
export const LOGIN_ROUTE = "/login"
export const REGISTER_ROUTE = "/register"

/**
 * One of DummyJSON's own users, filled into the sign-in form so the demo signs in with one click.
 * Delete it, and use empty default values in `LoginForm`, once you connect your API.
 */
export const DEMO_ACCOUNT = { username: "emilys", password: "emilyspass" } as const

/**
 * NIST SP 800-63B-4: 15 to 64 characters, no common passwords, repeats or personal details, and
 * no composition rules. Shared by the form and, through `@virastack/password/server`, your server.
 */
export const PASSWORD_POLICY = definePolicy({ preset: "nist" })

/** The longest username, for the mask and the schema. */
export const USERNAME_MAX_LENGTH = 50
/** The longest first or last name: the `fullName` preset's own limit, which the schema follows. */
export const NAME_MAX_LENGTH = 70

/**
 * What a username can hold, as the schema checks it: lowercase letters, digits, dots, hyphens and
 * underscores, up to 50. A capital letter typed becomes lowercase; anything else is not typed.
 */
const usernamePreset = definePreset("username", {
  mask: `u[${"u".repeat(USERNAME_MAX_LENGTH - 1)}]`,
  tokens: { u: /[a-z0-9._-]/i },
  transform: "lowercase",
  autoComplete: "username"
})

/** The masks, shared by each form and its resolver. */
export const LOGIN_MASKS = { username: usernamePreset } as const

/** `fullName` takes letters of any language, Turkish ones included, and single spaces. */
export const REGISTER_MASKS = {
  firstName: { preset: "fullName", autoComplete: "given-name" },
  lastName: { preset: "fullName", autoComplete: "family-name" },
  username: usernamePreset
} as const

import { ApiError } from "@/lib/api"

/** DummyJSON answers a wrong username or password with 400; most APIs use 401. */
export function isInvalidCredentials(error: unknown) {
  return (
    error instanceof ApiError && error.kind === "http" && [400, 401].includes(error.status ?? 0)
  )
}

